const j = $json;

// FROM: obiekt (mailparser) albo string
let fromStr = '', fromEmail = '';
if (j.from && typeof j.from === 'object') {
  fromStr = j.from.text || '';
  if (j.from.value && j.from.value[0]) fromEmail = (j.from.value[0].address || '').toLowerCase();
} else {
  fromStr = j.from || j.From || '';
}
if (!fromEmail) {
  const mm = String(fromStr).match(/<([^>]+)>/);
  fromEmail = (mm ? mm[1] : String(fromStr)).trim().toLowerCase();
}
const fromDomain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';

const subject = j.subject ?? j.Subject ?? '(brak tematu)';

const stripHtml = (s) => String(s)
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
  .replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

let bodyText = (j.text || j.textPlain || '').trim();
if (!bodyText && j.html) bodyText = stripHtml(j.html);
if (!bodyText && j.textAsHtml) bodyText = stripHtml(j.textAsHtml);
if (!bodyText) bodyText = j.snippet || '';

// Zalaczniki: 3 warstwy - binary (gdy downloadAttachments ON) -> json.attachments -> naglowek Content-Type
const atts = Array.isArray(j.attachments) ? j.attachments : [];
const binMap = ($input.item && $input.item.binary) ? $input.item.binary : {};
const binNames = Object.keys(binMap).map(k => (binMap[k] && (binMap[k].fileName || binMap[k].filename)) || k).filter(Boolean);
const jsonNames = atts.map(a => (a && (a.filename || a.name))).filter(Boolean);
const attachmentNames = binNames.length ? binNames : jsonNames;
const ctHeader = String((j.headers && (j.headers['content-type'] || j.headers['Content-Type'])) || '');
const hasAttachments = attachmentNames.length > 0 || ctHeader.toLowerCase().indexOf('multipart/mixed') !== -1;

const messageId = j.id ?? j.messageId ?? '';
const threadId = j.threadId ?? '';

return { json: { subject, from: fromStr, fromEmail, fromDomain, bodyText, messageId, threadId, hasAttachments, attachmentNames } };

// ROUTING + PILNOSC + BLOKI SLACK (przyciski, @mention, zalaczniki)
const TEAM = {
  zapytanie_ofertowe:   { owner:'Anna Nowak (Sprzedaz)', slackChannel:'sprzedaz', slackUserId:'' },
  pytanie_klienta:      { owner:'Marek Lis (PM)',        slackChannel:'klienci',  slackUserId:'' },
  reklamacja_eskalacja: { owner:'Kasia Zajac (Head)',    slackChannel:'eskalacje',slackUserId:'' },
  sprawy_fakturowe:     { owner:'Piotr Grosz (Finanse)', slackChannel:'finanse',  slackUserId:'' },
  wspolpraca_dostawca:  { owner:'Anna Nowak (Sprzedaz)', slackChannel:'sprzedaz', slackUserId:'' },
  rekrutacja:           { owner:'Kasia Zajac (Head)',    slackChannel:'hr',       slackUserId:'' },
  spam:                 { owner:'-',                     slackChannel:'szum',     slackUserId:'' },
  inne:                 { owner:'Marek Lis (PM)',        slackChannel:'do-triazu',slackUserId:'' }
};
const CRISIS = { owner:'Kasia Zajac (Head)', slackChannel:'kryzys', slackUserId:'' };
// DEMO: wpisz swoj Slack member ID (U...), zeby wszystkie pingi szly do Ciebie.
// PRODUKCJA: zostaw '' i wypelnij slackUserId per rola w TEAM/CRISIS.
const PING_OVERRIDE = 'U09352MCU9K';
const VIP_DOMAINS = ['kluczowyklient.pl','bigcorp.com'];
const URGENT_KEYWORDS = ['pilne','pilna','awaria','krytyczne','krytyczna','natychmiast','reklamacja','eskalacja'];

const judge = $json.output ?? $json;
const verdict = (judge && judge.verdict) ? judge.verdict : 'popraw';  // fail-closed
const judgeOk = verdict === 'ok';
const agentRaw = $('asystent-triazu').item.json;
const ai = agentRaw.output ?? agentRaw;
const norm = $('normalizacja').item.json;
const cat = TEAM[ai.category] ? ai.category : 'inne';
const t = TEAM[cat];

const hay = ((norm.subject||'') + ' ' + (norm.bodyText||'')).toLowerCase();
const kwHit = URGENT_KEYWORDS.some(function(k){ return hay.includes(k); });
const vipHit = VIP_DOMAINS.some(function(d){ return (norm.fromDomain||'').includes(d); });
const isUrgent = ai.urgency === 'urgent' || kwHit || vipHit;

const pick = function(uid){ return PING_OVERRIDE || uid || ''; };
const mentionOf = function(uid){ var u = pick(uid); return u ? ('<@' + u + '> ') : ''; };
const gmailUrl = 'https://mail.google.com/mail/u/0/#all/' + (norm.messageId || '');
const atts = Array.isArray(norm.attachmentNames) ? norm.attachmentNames : [];
const attLine = atts.length ? ('\n:paperclip: *Zalaczniki:* ' + atts.join(', ')) : '';
const jIssues = (judge && Array.isArray(judge.issues)) ? judge.issues : [];
const jReason = (judge && judge.reason) ? judge.reason : 'brak werdyktu sedziego (kontrola niedostepna)';
const judgeLine = judgeOk ? '' : ('\n:warning: *Kontrola jakosci:* ' + verdict + ' - ' + jReason + (jIssues.length ? ('\n> ' + jIssues.join('\n> ')) : ''));

const summary =
  mentionOf(t.slackUserId) + '*[' + cat + ']*' + (isUrgent ? ' :rotating_light: *PILNE*' : '') + '  ->  ' + t.owner + '\n' +
  '*Od:* ' + (norm.from||'') + '\n' +
  '*Temat:* ' + (norm.subject||'') + '\n' +
  '*Podsumowanie:* ' + (ai.summary||'') + '\n' +
  '*Pewnosc:* ' + (ai.confidence!=null?ai.confidence:'?') +
  (isUrgent ? ('  |  *Powod:* ' + (vipHit?'klient VIP':(kwHit?'slowo-klucz':(ai.urgency_reason||'AI')))) : '') +
  attLine + judgeLine + '\n' +
  '<' + gmailUrl + '|:email: Otworz w Gmailu>';

const draft = ai.draft_reply || '';
const subj = norm.subject || '';
const mid = norm.messageId || '';

const sendVal = JSON.stringify({ mid: mid, tid: (norm.threadId || ''), subj: subj, draft: draft });
const canSend = !!draft && sendVal.length < 1900 && judgeOk;  // sedzia decyduje o przycisku

const elements = [];
if (canSend) elements.push({ type:'button', text:{type:'plain_text', text:':white_check_mark: Wyslij szkic', emoji:true}, style:'primary', action_id:'wyslij_szkic', value: sendVal });
elements.push({ type:'button', text:{type:'plain_text', text:':raising_hand: Przejmuje', emoji:true}, action_id:'przejmuje', value: JSON.stringify({ subj: subj }) });

const draftText = draft ? (draft.length > 2900 ? draft.slice(0,2900) + '\n...' : draft) : '';
const draftBlock = draft ? [ { type:'section', text:{ type:'mrkdwn', text: '*Szkic (do review):*\n' + draftText } } ] : [];

const baseBlocks = [ { type:'section', text:{ type:'mrkdwn', text: summary } } ].concat(draftBlock).concat([ { type:'actions', elements: elements } ]);
const crisisTop = { type:'section', text:{ type:'mrkdwn', text: ':rotating_light: *TRYB PILNY* :rotating_light: <!here>\n' + summary } };
const crisisArr = [ crisisTop ].concat(draftBlock).concat([ { type:'actions', elements: elements } ]);

return { json: {
  category: cat, isUrgent: isUrgent, owner: t.owner,
  slackChannel: t.slackChannel, crisisChannel: CRISIS.slackChannel,
  blocksJson: JSON.stringify({ blocks: baseBlocks }),
  crisisBlocks: JSON.stringify({ blocks: crisisArr }),
  subject: subj, fallbackText: '[' + cat + '] ' + subj
} };

